export const html="<section class=\"section review-section\"><div class=\"wrap\">\n <span class=\"eyebrow\">MARIZ HQ / STAFF CONSOLE / COMPANIES</span>\n <h1>Company reviews</h1><p>Inspect evidence, record six checks and make an independently verified decision.</p>\n <nav class=\"pills\" aria-label=\"Console workspaces\"><a class=\"btn outline\" href=\"/console/\">Dashboard &amp; inboxes</a><a class=\"btn\" aria-current=\"page\" href=\"/console/company-reviews\">Companies / Reviews</a><button class=\"btn outline\" type=\"button\" id=\"review-permissions\">My permissions</button></nav>\n <p id=\"review-account\" class=\"tiny\">Checking administrator access…</p>\n <div id=\"review-notice\" class=\"notice\" role=\"status\" aria-live=\"polite\">Loading protected reviews…</div>\n <div class=\"review-layout\">\n  <section id=\"review-list\" aria-label=\"Company application queue\" tabindex=\"-1\">\n   <div class=\"review-list-heading\"><div><span class=\"eyebrow\">REVIEW WORKSPACE</span><h2>Applications</h2><p>Choose a company to open its review details.</p></div><p id=\"review-count\" class=\"review-count\" aria-live=\"polite\"></p></div>\n   <form id=\"review-filters\"><div class=\"field\"><label for=\"review-search\">Company or registration number</label><input id=\"review-search\" name=\"search\" type=\"search\" maxlength=\"80\"></div>\n    <div class=\"field\"><label for=\"review-status\">Application status</label><select name=\"status\" id=\"review-status\"><option value=\"all\">All submitted applications</option><option value=\"submitted\">Pending</option><option value=\"under_review\">Under review</option><option value=\"needs_information\">Additional information required</option><option value=\"approved\">Approved history</option><option value=\"rejected\">Rejected history</option></select></div>\n    <div class=\"field\"><label for=\"review-assigned\">Assigned reviewer</label><select name=\"assigned\" id=\"review-assigned\"><option value=\"all\">All reviewers</option><option value=\"me\">Assigned to me</option><option value=\"unassigned\">Unassigned</option></select></div><button class=\"btn\" type=\"submit\">Apply filters</button>\n   </form>\n   <div id=\"review-queue\" aria-label=\"Applications\"></div>\n   <nav class=\"pills\" aria-label=\"Queue pages\"><button id=\"review-prev\" class=\"btn outline\" type=\"button\" disabled>Previous</button><button id=\"review-next\" class=\"btn outline\" type=\"button\" disabled>Next</button></nav>\n  </section>\n  <section id=\"review-detail\" aria-label=\"Selected company\" tabindex=\"-1\" hidden></section>\n </div>\n</div></section>\n";
export const css=".review-section{padding:32px 0 50px}\r\n.review-section .wrap{max-width:1440px;padding:0 clamp(16px,3vw,48px)}\r\n.review-section h1{font:700 clamp(28px,4vw,44px)/1.15 Georgia,serif;margin:10px 0}\r\n.review-section h2{font:700 26px/1.3 Georgia,serif;margin:12px 0}\r\n.review-section h3{font-size:19px}\r\n.review-section p{overflow-wrap:anywhere}\r\n.review-layout{margin-top:24px}\r\n.review-list-heading{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:20px}\r\n.review-list-heading h2{margin:4px 0}\r\n.review-list-heading p{margin:0}\r\n.review-count{font-weight:700;color:var(--brown);white-space:nowrap}\r\n#review-filters{display:grid;grid-template-columns:minmax(220px,2fr) minmax(160px,1fr) minmax(160px,1fr) auto;align-items:end;gap:14px;padding:18px;background:#f4ebdd;border:1px solid var(--line);border-radius:12px;margin-bottom:22px}\r\n#review-filters .field{margin:0}\r\n#review-filters .btn{white-space:nowrap}\r\n.review-section input,.review-section select,.review-section textarea{max-width:100%;min-width:0}\r\n.review-section textarea{min-height:90px}\r\n.review-section button,.review-section summary,.review-section a.btn{min-height:44px}\r\n#review-queue{display:grid;gap:12px;margin:14px 0 20px}\r\n.review-item{display:grid;grid-template-columns:minmax(200px,2fr) minmax(110px,1fr) minmax(110px,1fr) minmax(160px,1.2fr) minmax(130px,1fr);align-items:center;gap:16px;width:100%;text-align:left;background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:18px 20px;color:var(--ink);overflow-wrap:anywhere}\r\n.review-item:hover,.review-item:focus-visible{border-color:var(--brown);box-shadow:0 3px 14px #392b2018}\r\n.review-item strong{font-size:18px}\r\n.review-item span{display:block}\r\n.review-item .review-cell-label{display:block;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);font-weight:700;margin-bottom:5px}\r\n.review-item .review-state{display:inline-block;border-radius:999px;background:#f4ebdd;padding:5px 10px;font-weight:700;color:var(--brown)}\r\n.review-back{margin-bottom:20px}\r\n#review-detail{max-width:1120px;margin:auto;scroll-margin-top:130px}\r\n.review-section dl{display:grid;grid-template-columns:minmax(100px,1fr) minmax(0,2fr);gap:8px 20px}\r\n.review-section dt{font-weight:700}\r\n.review-section dd{margin:0;overflow-wrap:anywhere}\r\n.review-section details{border-bottom:1px solid var(--line);padding:14px 0}\r\n.review-section summary{display:flex;align-items:center;cursor:pointer;font-weight:750;gap:12px}\r\n.review-section summary::before{content:'+'}\r\n.review-section details[open]>summary::before{content:'−'}\r\n.review-section .review-document{padding:12px 0;border-bottom:1px solid var(--line)}\r\n.review-section .review-document .pills{margin:10px 0}\r\n.review-viewer{margin:16px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#eee9e0}\r\n.review-viewer-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:10px 12px;background:var(--paper);border-bottom:1px solid var(--line)}\r\n.review-viewer-toolbar strong{margin-right:auto}\r\n.review-viewer-toolbar .btn{min-height:36px;padding:6px 12px}\r\n.review-viewer-viewport{height:min(76dvh,820px);min-height:380px;overflow:auto;background:#45423e}\r\n.review-viewer-stage{display:flex;align-items:center;justify-content:center;box-sizing:border-box;min-width:100%;min-height:100%;padding:12px}\r\n.review-viewer-image{display:block;max-width:none;max-height:none;flex:none;box-shadow:0 4px 24px #0006;background:white}\r\n.review-viewer iframe{display:block;width:100%;height:min(76dvh,820px);min-height:380px;border:0;background:#45423e;margin:0}\r\n.review-viewer-help{margin:0;padding:8px 12px;color:var(--muted);font-size:13px;background:var(--paper)}\r\n.review-section progress{width:100%;height:16px;accent-color:var(--brown)}\r\n.review-section .decision-box{padding:18px;background:#f4ebdd;border-radius:10px;margin:18px 0}\r\n.review-section .decision-box input[type=checkbox]{width:22px;height:22px;vertical-align:middle;margin-right:10px}\r\n.review-section .review-timeline{padding-left:22px}\r\n.review-section .review-timeline li{margin:12px 0;overflow-wrap:anywhere}\r\n.review-section [hidden]{display:none!important}\r\n.review-section .pill{white-space:normal}\r\n.identity img{background:#21180f;border-radius:8px;object-fit:contain}\r\nbutton:disabled{cursor:not-allowed}\r\n#review-detail:focus,#review-list:focus{outline:2px solid var(--gold);outline-offset:8px}\r\n@media(max-width:980px){#review-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.review-item{grid-template-columns:repeat(2,minmax(0,1fr))}.review-item strong{grid-column:1/-1}}\r\n@media(max-width:600px){.review-list-heading{display:block}.review-count{margin-top:10px!important}#review-filters{grid-template-columns:1fr}.review-item{grid-template-columns:1fr;gap:10px}.review-item strong{grid-column:auto}.review-section .pills>*{flex-grow:1}.review-section dl{grid-template-columns:1fr;gap:4px}.review-section dd{margin-bottom:12px}.review-section .decision-box{padding:14px}.review-viewer-viewport,.review-viewer iframe{height:62dvh;min-height:300px}}\r\n\r\n.review-documents,.review-checklist{margin:28px 0}.review-document-group{border:1px solid var(--line);border-radius:12px;padding:18px;margin:16px 0;background:var(--paper)}.review-document-group h4{font-size:18px;margin:0 0 12px}.review-document-group .review-document:last-child{border:0}.review-missing,.review-warning{padding:12px 16px;background:#f4ebdd;border-left:3px solid var(--gold);border-radius:6px}\r\n\r\n#review-detail{max-width:1320px}.review-workspace{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:28px;align-items:start}.review-content{min-width:0}.review-content>dl,.review-content>details,.review-documents{scroll-margin-top:115px}.review-content>dl{margin-top:8px}.review-sidebar{position:sticky;top:110px;max-height:calc(100dvh - 126px);overflow-y:auto;border:1px solid var(--line);border-radius:12px;background:var(--paper);padding:16px}.review-sidebar h3{margin:0 0 8px}.review-sidebar>p{margin:8px 0}.review-check-row{padding:12px 0;border-top:1px solid var(--line)}.review-check-label,.review-issue-label{display:flex;align-items:flex-start;gap:10px;cursor:pointer;line-height:1.4}.review-check-label{font-weight:700}.review-sidebar input[type=checkbox]{appearance:auto;width:21px;height:21px;flex:none;margin:0;accent-color:var(--brown)}.review-check-extras{border:0!important;padding:0!important;margin-left:31px}.review-check-extras summary{font-size:13px;font-weight:400;min-height:30px}.review-check-extras textarea{min-height:65px}.review-check-extras .field{margin:12px 0}.review-issue-label{font-size:14px;margin:12px 0}.review-jump{border:0;background:none;color:var(--brown);text-decoration:underline;font:inherit;font-size:12px;padding:0;margin-left:31px;cursor:pointer;min-height:26px!important}.review-save-area{position:sticky;bottom:-16px;margin:8px -16px -16px;padding:12px 16px;background:var(--paper);border-top:1px solid var(--line);box-shadow:0 -4px 10px #392b2008;z-index:2}.review-save-area .btn{width:100%}.review-save-area p{margin:5px 0 8px}.review-draft-status{font-size:13px;font-weight:700}.review-unsaved{box-shadow:inset 3px 0 var(--gold);padding-left:10px!important}.review-content .review-document .field{margin:10px 0;max-width:360px}.review-document-group{margin-top:14px}.review-documents{margin:22px 0}.review-content details{margin-top:10px}\r\n@media(max-width:900px){.review-workspace{grid-template-columns:minmax(0,1fr) 285px;gap:16px}.review-sidebar{padding:12px}.review-save-area{margin-left:-12px;margin-right:-12px;padding:12px;bottom:-12px}}\r\n@media(max-width:700px){.review-workspace{display:flex;flex-direction:column}.review-sidebar{order:-1;position:static;width:100%;box-sizing:border-box;max-height:none;overflow:visible}.review-check-row{padding:10px 0}.review-save-area{position:fixed;bottom:0;left:0;right:0;margin:0;padding:10px 16px;box-shadow:0 -3px 12px #392b2020;border-top:1px solid var(--line);z-index:10}.review-save-area .tiny{display:none}#review-detail{padding-bottom:130px}.review-content{width:100%}.review-document-group{padding:14px}}\r\n\r\n.review-sidebar{font-size:14px}.review-check-extras:not([open]){display:inline-block;vertical-align:middle}.review-check-row .review-jump{display:inline-block;vertical-align:middle;margin-left:8px;font-size:11px}.review-check-extras summary{font-size:12px}.review-check-label{font-size:14px}\r\n\r\n.review-sidebar{box-sizing:border-box}.review-check-row{padding-top:8px;padding-bottom:8px}.review-check-extras summary{min-height:24px}.review-check-row .review-jump{min-height:24px!important}.review-save-area .tiny{font-size:11px;line-height:1.35}\r\n\r\n.review-workspace{row-gap:0}.review-heading{grid-column:1;grid-row:1}.review-content{grid-column:1;grid-row:2}.review-sidebar{grid-column:2;grid-row:1/span 2}@media(max-width:700px){.review-heading{order:0;width:100%}.review-sidebar{order:1}.review-content{order:2}}\r\n\r\n.review-resubmitted{border-left:5px solid #28758a!important;background:#edf7f8!important}.review-resubmitted-notice{padding:14px;border-left:4px solid #28758a;background:#edf7f8}.review-applicant-message{border:1px solid var(--line);padding:18px;border-radius:12px;margin-bottom:20px}.review-message-text{white-space:pre-wrap;overflow-wrap:anywhere}.review-save-area .btn{margin-top:6px}.review-decision{scroll-margin-top:110px}@media(max-width:700px){.review-save-area{display:flex;gap:6px;flex-wrap:wrap}.review-save-area .review-draft-status{flex-basis:100%;margin:0}.review-save-area .btn{width:auto;flex:1;padding:8px;font-size:12px;min-height:40px}.review-save-area .tiny{display:none}#review-detail{padding-bottom:150px}}\r\n";
export const js="// BEGIN REVIEW DRAFT\n// UI draft only. Every write still uses the existing authenticated, audited APIs.\nfunction createReviewDraft(data) {\n const baseChecks=new Map(data.checks.map(c=>[c.code,{result:c.result,note:c.note||''}]));\n const baseDocuments=new Map(data.documents.map(d=>[d.id,d.status]));\n const pendingChecks=new Map(),pendingDocuments=new Map();\n let saving=false;\n const same=(a,b)=>a.result===b.result&&a.note===b.note;\n const currentCheck=code=>({...pendingChecks.get(code)||baseChecks.get(code)||{result:'needs_review',note:''}});\n const changes=()=>[\n  ...[...pendingDocuments].map(([document,status])=>({action:'evidence',data:{document,status}})),\n  ...[...pendingChecks].map(([code,value])=>({action:'check',data:{application:data.application.id,code,...value}})),\n ];\n return {\n  check:currentCheck,\n  savedCheck:code=>({...baseChecks.get(code)||{result:'needs_review',note:''}}),\n  document:id=>pendingDocuments.get(id)||baseDocuments.get(id),\n  get pendingCount(){return pendingChecks.size+pendingDocuments.size;},\n  get saving(){return saving;},\n  setCheck(code,value){\n   if(saving)throw Error('Review save is in progress');\n   if(!['registry','identity','authority','documents','duplicate','contact'].includes(code)||!['needs_review','pass','fail'].includes(value.result)||typeof value.note!=='string'||value.note.length>2000)throw Error('Invalid review check');\n   const next={result:value.result,note:value.note};\n   if(same(next,baseChecks.get(code)||{result:'needs_review',note:''}))pendingChecks.delete(code);else pendingChecks.set(code,next);\n  },\n  setDocument(id,status){\n   if(saving)throw Error('Review save is in progress');\n   if(!baseDocuments.has(id)||(!['accepted','rejected'].includes(status)&&status!==baseDocuments.get(id)))throw Error('Invalid document result');\n   if(status===baseDocuments.get(id))pendingDocuments.delete(id);else pendingDocuments.set(id,status);\n  },\n  changes,\n  async save(send){\n   if(saving)throw Error('Review save is already in progress');\n   const pending=changes();let saved=0;saving=true;\n   try{\n    for(const change of pending){\n     await send(change.action,change.data);\n     if(change.action==='evidence'){baseDocuments.set(change.data.document,change.data.status);pendingDocuments.delete(change.data.document);}\n     else{baseChecks.set(change.data.code,{result:change.data.result,note:change.data.note});pendingChecks.delete(change.data.code);}\n     saved++;\n    }\n    return {saved,total:pending.length};\n   }catch(cause){const error=new Error('Review save incomplete');error.saved=saved;error.total=pending.length;error.cause=cause;throw error;}\n   finally{saving=false;}\n  },\n };\n}\n\n// END REVIEW DRAFT\n(() => {\r\n 'use strict';\r\n const $=id=>document.getElementById(id),queue=$('review-queue'),detail=$('review-detail'),notice=$('review-notice');\r\n const checks=['registry','identity','authority','documents','duplicate','contact'];\r\n const names={submitted:'Pending',under_review:'Under review',needs_information:'Additional information required',approved:'Approved',rejected:'Rejected',registry:'SSM business details',identity:'Owner / representative IC',authority:'Permission to represent the business',documents:'Document completeness',duplicate:'Duplicate or conflicting business',contact:'Business contact details',registration_profile:'Business registration (SSM)',identity_document:'Owner / representative identity (IC)',registration_certificate:'SSM registration certificate (supporting)',authority_letter:'Authorisation letter',other:'Other supporting document',uploaded:'Awaiting document review',accepted:'Accepted',needs_review:'Not checked',pass:'Passed',fail:'Issue found'};\r\n names.identity='Owner / representative verification';names.identity_document='Owner / representative identity (IC, optional)';\n const checkHelp={registry:'Compare the business name and registration number with the SSM business profile. Confirm the registration details are current.',identity:'Verify the owner or representative using the SSM details and supporting authority or contact evidence. IC is optional. If an IC was provided, inspect it and record any issues. Record how identity was verified in the notes.',authority:'Confirm the applicant is the business owner, or has permission to act for the business. For a representative, inspect the authorisation letter.',documents:'Confirm the required SSM document is readable, complete and accepted. IC and other supporting documents are optional; review any that were provided. Repeated copies do not count as different documents.',duplicate:'Check for another MARIZ company using the same registration number, or business details that conflict with this application.',contact:'Check the submitted business email and contact details against the business records or a recorded contact confirmation.'};\n let page=0,selected=null,epoch=0,identity=null,activeDraft=null;\r\n const canLeave=()=>!activeDraft?.pendingCount||window.confirm(\"Discard unsaved review changes?\");\r\n const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(cls)e.className=cls;return e;};\r\n const say=(text,error=false)=>{notice.textContent=text;notice.setAttribute('role',error?'alert':'status');};\r\n const date=value=>value?new Date(value).toLocaleString():'Not submitted';\r\n const label=value=>names[value]||String(value||'Not recorded').replaceAll('_',' ');\r\n async function api(action,data={},post=false){\r\n  const url='/console/api/company-reviews/'+action+(post?'':'?'+new URLSearchParams(data));\r\n  let r;\r\n  try{r=await fetch(url,{method:post?'POST':'GET',credentials:'same-origin',cache:'no-store',redirect:'error',headers:post?{'content-type':'application/json'}:{},body:post?JSON.stringify(data):undefined});}\r\n  catch{throw Error('The protected console connection was interrupted. Your administrator session may have expired. Reload this page and sign in again if prompted, then reopen the application before retrying. A code request is not confirmed until this page reports it was accepted.');}\r\n  const body=await r.json().catch(()=>({}));if(!r.ok)throw Error(body.error||'Protected review service unavailable');return body;\r\n }\r\n const button=(text,handler,cls='btn outline')=>{const b=el('button',text,cls);b.type='button';b.addEventListener('click',async()=>{b.disabled=true;try{await handler();}catch(e){say(e.message,true);}finally{if(b.isConnected)b.disabled=false;}});return b;};\r\n function field(form,text,name,type='textarea',value=''){\r\n  const wrap=el('div',undefined,'field'),id='review-'+name+'-'+crypto.randomUUID(),lab=el('label',text),input=el(type==='textarea'?'textarea':'input');\r\n  lab.htmlFor=id;input.id=id;input.name=name;if(type!=='textarea')input.type=type;input.value=value;input.maxLength=2000;wrap.append(lab,input);form.append(wrap);return input;\r\n }\r\n function options(form,text,name,items,value){\r\n  const wrap=el('div',undefined,'field'),id='review-'+name+'-'+crypto.randomUUID(),lab=el('label',text),input=el('select');lab.htmlFor=id;input.id=id;input.name=name;\r\n  for(const [v,title] of items){const o=el('option',title);o.value=v;o.selected=v===value;input.append(o);}wrap.append(lab,input);form.append(wrap);return input;\r\n }\r\n const cell=(title,value,cls)=>{const e=el('span',undefined,cls);e.append(el('span',title,'review-cell-label'),el('span',value));return e;};\r\n function showList(){if(activeDraft?.saving||!canLeave())return;activeDraft=null;selected=null;$('review-list').hidden=false;detail.hidden=true;detail.replaceChildren();$('review-list').focus();say('Choose an application to review.');}\r\n function openViewer(box,d){\r\n  box.querySelector('.review-viewer')?.remove();\r\n  const url='/console/api/company-reviews/document?document='+encodeURIComponent(d.id);\r\n  const viewer=el('div',undefined,'review-viewer'),toolbar=el('div',undefined,'review-viewer-toolbar');toolbar.append(el('strong','Private '+label(d.kind)));viewer.append(toolbar);\r\n  if(d.mime_type==='application/pdf'){\r\n   const frame=el('iframe');frame.title='Private '+label(d.kind)+' PDF';frame.referrerPolicy='no-referrer';frame.src=url+'#view=Fit';\r\n   toolbar.append(button('Fit page',()=>{frame.src=url+'#view=Fit';}),button('100%',()=>{frame.src=url+'#zoom=100';}));\r\n   viewer.append(frame,el('p','Use the PDF viewer controls to zoom, change pages or print. The document stays in this protected console.','review-viewer-help'));\r\n  }else if(['image/jpeg','image/png'].includes(d.mime_type)){\r\n   const viewport=el('div',undefined,'review-viewer-viewport'),stage=el('div',undefined,'review-viewer-stage'),image=el('img',undefined,'review-viewer-image');image.alt='Private '+label(d.kind);image.src=url;\r\n   let scale=1,fitScale=1,fitted=true;\r\n   const zoomLabel=el('output','Fit page');zoomLabel.setAttribute('aria-label','Document zoom');toolbar.append(zoomLabel);\r\n   const apply=()=>{const width=Math.max(1,Math.round(image.naturalWidth*scale)),height=Math.max(1,Math.round(image.naturalHeight*scale));zoomLabel.textContent=Math.round(scale*100)+'%';image.style.width=width+'px';image.style.height=height+'px';stage.style.width=Math.max(viewport.clientWidth,width+24)+'px';stage.style.height=Math.max(viewport.clientHeight,height+24)+'px';};\r\n   const fit=()=>{if(!image.naturalWidth)return;fitScale=Math.min(1,(viewport.clientWidth-24)/image.naturalWidth,(viewport.clientHeight-24)/image.naturalHeight);fitted=true;scale=fitScale;apply();viewport.scrollTo(0,0);};\r\n   image.onload=fit;\r\n   const resize=new ResizeObserver(()=>{if(!viewer.isConnected){resize.disconnect();return;}if(fitted)fit();else apply();});resize.observe(viewport);image.onerror=()=>say('Private document could not be displayed. Check your administrator session and retry.',true);\r\n   toolbar.append(button('Fit page',fit),button('100%',()=>{fitted=false;scale=1;apply();}),button('Zoom out',()=>{fitted=false;scale=Math.max(Math.min(fitScale,.1),scale/1.25);apply();}),button('Zoom in',()=>{fitted=false;scale=Math.min(4,scale*1.25);apply();}));\r\n   stage.append(image);viewport.append(stage);viewer.append(viewport,el('p','The full page is shown first. Use zoom controls to inspect details.','review-viewer-help'));\r\n  }else{say('Unsupported private document format.',true);return;}\r\n  box.append(viewer);say('Private document opened at fit-to-page size. Inspect it before accepting.');\r\n }\r\n async function loadQueue(){\r\n  const ticket=++epoch;say('Loading applications…');queue.setAttribute('aria-busy','true');\r\n  try{\r\n   const filter=Object.fromEntries(new FormData($('review-filters'))),data=await api('queue',{...filter,page:String(page)});if(ticket!==epoch)return;\r\n   queue.replaceChildren();$('review-count').textContent=data.total+' application(s) · Page '+(page+1);\r\n   for(const app of data.applications){const b=button('',()=>loadDetail(app.id),'review-item');b.setAttribute('aria-label','Open review for '+app.legal_name);b.append(el('strong',app.legal_name),cell('Registration',app.registration_no),cell('Status',app.status==='needs_information'?'Awaiting applicant changes':app.resubmission_count>0&&['submitted','under_review'].includes(app.status)?'Resubmitted · Review again':label(app.status),'review-state-cell'),cell('Submitted',date(app.submitted_at)),cell('Reviewer',app.assigned_email||'Unassigned'));b.classList.toggle('review-resubmitted',app.resubmission_count>0&&['submitted','under_review'].includes(app.status));b.dataset.application=app.id;queue.append(b);}\r\n   if(!data.applications.length)queue.append(el('p','No applications match these filters. Your own companies are excluded.'));\r\n   $('review-prev').disabled=page===0;$('review-next').disabled=(page+1)*data.page_size>=data.total;say('Queue updated.');\r\n  }catch(e){if(ticket===epoch){queue.replaceChildren();say(e.message,true);}}finally{if(ticket===epoch)queue.removeAttribute('aria-busy');}\r\n }\r\n async function loadDetail(id,focus=true){\r\n  selected=id;detail.setAttribute('aria-busy','true');say('Loading company review…');\r\n  try{const data=await api('detail',{application:id});if(selected!==id)return;renderDetail(data);$('review-list').hidden=true;detail.hidden=false;if(focus){detail.focus({preventScroll:true});detail.scrollIntoView({block:'start'});}say('Company loaded. Review changes are saved only when you choose Save review.');return true;}\r\n  catch(e){if(selected===id){detail.replaceChildren(button('← Back to applications',showList,'btn outline review-back'),el('h2','Company unavailable'));$('review-list').hidden=true;detail.hidden=false;detail.focus();say(e.message,true);}return false;}finally{if(selected===id)detail.removeAttribute('aria-busy');}\r\n }\r\n function renderDetail(data){\r\n  const app=data.application,company=data.company,editable=['submitted','under_review'].includes(app.status);detail.replaceChildren(button('← Back to applications',showList,'btn outline review-back'),el('span',label(app.status),'pill'),el('h2',company.legal_name));\r\n  const workspace=el('div',undefined,'review-workspace'),content=el('div',undefined,'review-content'),sidebar=el('aside',undefined,'review-sidebar');sidebar.setAttribute('aria-label','Review checks and page save');const heading=el('div',undefined,'review-heading');heading.append(...Array.from(detail.childNodes));workspace.append(heading,content,sidebar);detail.append(workspace);\r\n  const draft=createReviewDraft(data);activeDraft=draft;const draftControls=[],decisionControls=[],rows=new Map(),documentRows=new Map();let saveButton,savedCount;\r\n  const draftStatus=el('p',undefined,'review-draft-status');draftStatus.setAttribute('role','status');draftStatus.setAttribute('aria-live','polite');\r\n  const refreshDraft=()=>{const count=draft.pendingCount,pending=draft.changes();for(const [code,row] of rows)row.classList.toggle('review-unsaved',pending.some(c=>c.action==='check'&&c.data.code===code));for(const [id,row] of documentRows)row.classList.toggle('review-unsaved',pending.some(c=>c.action==='evidence'&&c.data.document===id));if(savedCount)savedCount.textContent=checks.filter(code=>draft.savedCheck(code).result==='pass').length+' of 6 checks saved as passed';draftStatus.textContent=draft.saving?'Saving review…':count?count+' unsaved change'+(count===1?'':'s'):'All review changes saved';if(saveButton)saveButton.disabled=!count||draft.saving;for(const control of draftControls)control.disabled=!editable||draft.saving;for(const control of decisionControls)control.disabled=!!count||draft.saving;};\r\n  if(app.resubmission_count>0)content.append(el('p','Applicant resubmitted '+date(app.submitted_at)+'. Review the updated documents and complete the checks again.','review-resubmitted-notice'));\r\n  const lastDecision=[...data.decisions].sort((a,b)=>new Date(b.at)-new Date(a.at))[0];\r\n  if(lastDecision){const message=el('section',undefined,'review-applicant-message');message.append(el('h3','Message to applicant'),el('p',lastDecision.reason,'review-message-text'));const notices=data.notifications||[],sent=notices.filter(n=>n.status==='sent').length,pending=notices.filter(n=>n.status==='pending').length;message.append(el('p','Workspace message available · Email: '+(notices.length?sent+' of '+notices.length+' accepted by email provider':'No email recipients recorded'),'tiny'));if(notices.some(n=>['sending','uncertain'].includes(n.status)))message.append(el('p','Email delivery is unconfirmed. Check the sender logs before attempting another send.','tiny'));if(pending)message.append(button('Retry pending email',async()=>{await api('notify',{application:app.id},true);await loadDetail(app.id,false);say('Email retry completed. Check the message status.');}));content.append(message);}\r\n  const info=el('dl');for(const [title,value] of [['Registration',company.registration_no],['Entity type',company.entity_type],['Registered address',company.registered_address||'Not recorded'],['Business email',company.business_email||'Not recorded'],['Submitted',date(app.submitted_at)],['Verification',label(company.verification_status)]])info.append(el('dt',title),el('dd',value));content.append(info);\r\n  const owners=el('details'),os=el('summary','Business owners & administrators');owners.append(os);for(const o of data.owners)owners.append(el('p',(o.name||o.email)+' · '+o.email+' · '+o.role));content.append(owners);\r\n  const docs=el('section',undefined,'review-documents');docs.append(el('h3','1. Review submitted documents'),el('p','Open each file, confirm what it contains, then select a document result. Save all changes using Save review beside the company details. Files are grouped by the category selected at upload.'));\r\n const documentGroups=[['Business registration (SSM)',['registration_profile']],['Owner / representative identity (IC, optional)',['identity_document']],['Supporting documents',['registration_certificate','authority_letter','other']]];\n  for(const [title,kinds] of documentGroups){const group=el('section',undefined,'review-document-group');group.append(el('h4',title));\r\n   const documents=data.documents.filter(d=>kinds.includes(d.kind));\r\n   if(!documents.length)group.append(el('p',kinds[0]==='identity_document'?'Optional — no IC document submitted. Verify the owner or representative using the available evidence.':kinds[0]==='other'||title==='Supporting documents'?'No supporting documents submitted.':'Missing — ask the applicant to upload this document using “Return for changes” beside Save review.','review-missing'));\n   documents.forEach((d,index)=>{const box=el('div',undefined,'review-document');box.append(el('strong',label(d.kind)+' · File '+(index+1)),el('p',label(d.status)+' · '+Math.ceil(d.size_bytes/1024)+' KB'+(d.created_at?' · Uploaded '+date(d.created_at):''),'tiny'));\n    if(lastDecision?.decision==='needs_information'&&d.created_at&&new Date(d.created_at)>new Date(lastDecision.at))box.append(el('p','New upload since changes were requested','review-resubmitted-notice'));\n    if(d.duplicate_count>1)box.append(el('p','Duplicate file — the same file was uploaded '+d.duplicate_count+' times. It does not count as another required document.','review-warning'));\r\n    const actions=el('div',undefined,'pills');actions.append(button('View document',async()=>openViewer(box,d)));\r\n    const download=el('a','Open in new tab','btn outline');download.href='/console/api/company-reviews/document?document='+encodeURIComponent(d.id);download.target='_blank';download.rel='noopener noreferrer';actions.append(download);\r\n    box.append(actions);\r\n    if(editable){const choices=[[d.status,label(d.status)],...['accepted','rejected'].filter(v=>v!==d.status).map(v=>[v,v==='accepted'?'Accept document':'Needs correction'])],result=options(box,'Review result for '+label(d.kind)+' file '+(index+1),'document-'+d.id,choices,d.status);draftControls.push(result);documentRows.set(d.id,box);result.addEventListener('change',()=>{draft.setDocument(d.id,result.value);box.classList.toggle('review-unsaved',draft.document(d.id)!==d.status);refreshDraft();});}\r\n    group.append(box);\r\n   });docs.append(group);\r\n  }content.append(docs);\r\n  const passed=checks.filter(code=>data.checks.some(c=>c.code===code&&c.result==='pass')).length;\r\n  savedCount=el('p',passed+' of 6 checks saved as passed','review-check-count');sidebar.append(el('h3','Review checks'),el('p','Tick each check after verifying the details.','tiny'),savedCount);\r\n  const targets={registry:'Business registration (SSM)',identity:'Owner / representative identity (IC)',authority:'Business owners & administrators',documents:'Submitted documents',duplicate:'Company details',contact:'Company details'};\r\n  const jumpTargets={registry:docs,identity:docs,authority:owners,documents:docs,duplicate:info,contact:info};\r\n  for(const code of checks){const current=draft.check(code),row=el('div',undefined,'review-check-row'),labelWrap=el('label',undefined,'review-check-label'),tick=el('input'),title=el('span',label(code));tick.type='checkbox';tick.checked=current.result==='pass';tick.setAttribute('aria-label','Verified: '+label(code));labelWrap.append(tick,title);row.append(labelWrap);\r\n   const extras=el('details',undefined,'review-check-extras');extras.open=current.result==='fail';extras.append(el('summary','Notes / issue'),el('p',checkHelp[code],'tiny'));\r\n   const issueLabel=el('label',undefined,'review-issue-label'),issue=el('input');issue.type='checkbox';issue.checked=current.result==='fail';issue.setAttribute('aria-label','Issue found: '+label(code));issueLabel.append(issue,'Issue found');extras.append(issueLabel);\r\n   const note=field(extras,'Notes: '+label(code),'note-'+code,'textarea',current.note);note.maxLength=2000;row.append(extras);\r\n   const jump=button('View',()=>{const target=jumpTargets[code];if(target===owners)owners.open=true;target.scrollIntoView({block:'start',behavior:'smooth'});},'review-jump');jump.setAttribute('aria-label','View '+targets[code]);row.append(jump);\r\n   const update=()=>{draft.setCheck(code,{result:tick.checked?'pass':issue.checked?'fail':'needs_review',note:note.value});row.classList.toggle('review-unsaved',draft.changes().some(c=>c.action==='check'&&c.data.code===code));refreshDraft();};\r\n   tick.addEventListener('change',()=>{if(tick.checked)issue.checked=false;update();});issue.addEventListener('change',()=>{if(issue.checked)tick.checked=false;update();});note.addEventListener('input',update);draftControls.push(tick,issue,note);rows.set(code,row);sidebar.append(row);\r\n  }\r\n  const saveArea=el('div',undefined,'review-save-area');saveArea.append(draftStatus);\r\n  if(editable){saveButton=button('Save review',async()=>{\r\n   if(!draft.pendingCount||draft.saving)return;\r\n   const operation=draft.save((action,values)=>api(action,values,true));refreshDraft();\r\n   try{const result=await operation;if(await loadDetail(app.id,false))say('Review saved: '+result.saved+' change'+(result.saved===1?'':'s')+'. Final approval is separate.');}\r\n   catch(error){refreshDraft();const saved=Number(error.saved)||0,total=Number(error.total)||0;draftStatus.textContent='Save incomplete: '+saved+' of '+total+' changes saved. Retry Save review for the remaining changes.';say(draftStatus.textContent+' '+(error.cause?.message||'Please retry.'),true);}\r\n  },'btn');saveArea.append(saveButton,el('p','Saves checkboxes, notes and document results. Does not approve the company.','tiny'));}else saveArea.append(el('p','This application is read-only.','tiny'));\r\n  sidebar.append(saveArea);refreshDraft();\r\n  if(editable){const decision=el('section',undefined,'review-decision');decision.hidden=true;decision.append(el('h3','Send decision to applicant'));const form=el('form',undefined,'decision-box'),choice=options(form,'Decision','decision',[['','Choose a decision…'],['needs_information','Return for changes'],['rejected','Reject application'],['approved','Approve & welcome']],'');choice.required=true;choice.querySelector('[value=\"\"]').disabled=true;\r\n   const canApprove=passed===6&&data.documents.some(d=>d.kind==='registration_profile'&&d.status==='accepted');choice.querySelector('[value=approved]').disabled=!canApprove;if(!canApprove)form.append(el('p','To approve: accept the SSM document and pass all six current checks. IC is optional.','tiny'));\n   const reason=field(form,'Message to applicant — explain the changes needed or welcome them onboard','reason');reason.placeholder='For changes: list each correction and the document needed. This message appears in the applicant workspace and email.';reason.required=true;reason.minLength=4;\n   const otp={value:''};\n   const confirmWrap=el('p'),confirmLabel=el('label'),confirm=el('input');confirm.type='checkbox';confirm.required=true;confirmLabel.append(confirm,'I inspected the evidence and confirm this decision and its reason.');confirmWrap.append(confirmLabel);form.append(confirmWrap);\r\n   form.append(button('Confirm & notify applicant',async()=>{if(!form.reportValidity()||!confirm.checked)return;if(choice.value!=='needs_information'&&!window.confirm('Record '+label(choice.value)+' for '+company.legal_name+'? This is an audited company decision.'))return;await api('decision',{application:app.id,decision:choice.value,reason:reason.value,otp:otp.value,confirm:true},true);otp.value='';await loadQueue();await loadDetail(app.id,false);say('Decision saved and published in the applicant workspace. Check the email status above.');},'btn'));form.addEventListener('submit',e=>e.preventDefault());decisionControls.push(...form.querySelectorAll('input,textarea,select,button'));decision.append(el('p','Save review changes before requesting a code or recording a final decision.','tiny'),form);const openDecision=value=>{decision.hidden=false;choice.value=value;if(value==='approved'&&!reason.value)reason.value='Welcome onboard! Your company verification is approved. Sign in to your MARIZ workspace to continue.';decision.scrollIntoView({block:'start',behavior:'smooth'});reason.focus({preventScroll:true});};\n   const returnButton=button('Return for changes',()=>openDecision('needs_information'),'btn outline'),approveButton=button('Approve & welcome',()=>openDecision('approved'),'btn');approveButton.disabled=!canApprove;saveArea.append(returnButton,approveButton);decisionControls.push(returnButton);if(canApprove)decisionControls.push(approveButton);if(!canApprove)saveArea.append(el('p','Approval requires six passed current checks and accepted SSM. IC is optional.','tiny'));\n   decision.querySelector('.tiny').textContent='Approval requires accepted SSM and all six current checks passed. IC is optional.';\n   content.append(decision);refreshDraft();\n  }else content.append(el('p','This application is read-only. Additional information must be resubmitted by the company before another review.','notice'));\r\n  const history=el('details');history.append(el('summary','Decision & activity history'));const timeline=el('ol',undefined,'review-timeline');for(const d of data.decisions)timeline.append(el('li',label(d.decision)+' · '+date(d.at)+' · '+d.reason));for(const a of data.audit)timeline.append(el('li',label(a.event_type)+' · '+date(a.created_at)));if(!timeline.children.length)timeline.append(el('li','No prior review activity.'));history.append(timeline);content.append(history);\r\n }\r\n window.addEventListener('beforeunload',event=>{if(activeDraft?.pendingCount||activeDraft?.saving){event.preventDefault();event.returnValue='';}});\r\n $('review-filters').addEventListener('submit',e=>{e.preventDefault();page=0;loadQueue();});$('review-prev').onclick=()=>{if(page>0){page--;loadQueue();}};$('review-next').onclick=()=>{page++;loadQueue();};\r\n $('review-permissions').onclick=()=>say(identity?'Signed in as '+identity.email+'. Independent KYB reviewer; private evidence and final decisions are audited. Billing and permission changes are outside this review module.':'Administrator identity has not been verified.');\r\n api('session').then(data=>{identity=data;$('review-account').textContent='Administrator: '+data.email+(data.environment==='staging'?' · STAGING — synthetic company testing':'');loadQueue();}).catch(e=>{say(e.message,true);$('review-account').textContent='Native review service is not enabled. No company data has been loaded.';for(const e of $('review-filters').elements)e.disabled=true;});\r\n})();\r\n";
